WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.OwnerUserId, p.CreationDate, p.Score, ROW_NUMBER() OVER (PARTITION BY p.OwnerUserId ORDER BY p.Score DESC NULLS FIRST) AS PostRank FROM Posts AS p WHERE p.CreationDate >= CAST('2023-01-01' AS Nullable(DATE)) AND p.Score > 0), TopUsers AS (SELECT u.Id AS UserId, u.DisplayName, COUNT(p.Id) AS PostCount, SUM(p.Score) AS TotalScore FROM Users AS u JOIN Posts AS p ON u.Id = p.OwnerUserId GROUP BY u.Id, u.DisplayName HAVING COUNT(p.Id) > 10 AND SUM(p.Score) > 100), UserBadges AS (SELECT b.UserId, GROUP_CONCAT(b.Name, ', ') AS BadgeNames FROM Badges AS b GROUP BY b.UserId) SELECT tu.DisplayName, tu.PostCount, tu.TotalScore, COALESCE(ub.BadgeNames, 'No Badges') AS BadgeNames, rp.Title AS TopPostTitle, rp.CreationDate AS TopPostDate FROM TopUsers AS tu LEFT JOIN UserBadges AS ub ON tu.UserId = ub.UserId LEFT JOIN RankedPosts AS rp ON tu.UserId = rp.OwnerUserId AND rp.PostRank = 1 ORDER BY tu.TotalScore DESC NULLS FIRST FETCH FIRST 10 ROWS ONLY